    Uses only integer and exact-string operations, so the result does not
    depend on the active decimal context precision.
    """
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, str):
        if _AMOUNT_STRING.fullmatch(value) is None:
            raise ValueError("invalid amount string")
        value = Decimal(value)  # exact conversion
    elif isinstance(value, int):
        value = Decimal(value)  # exact conversion
    elif not isinstance(value, Decimal):
        raise ValueError("amount must be a Decimal, int, or str")

    if not value.is_finite():
        raise ValueError("amount must be finite")
    if value.is_zero():
        raise ValueError("amount must be nonzero")
    sign, digits, exponent = value.as_tuple()
    if sign:
        raise ValueError("amount must be positive")
    # Magnitude check before any sizeable arithmetic: the value must lie in
    # [0.01, 1000000.00], i.e. its most significant digit is at 10^-2..10^6.
    adjusted = value.adjusted()
    if adjusted < -2 or adjusted > 6:
        raise ValueError("amount out of range")

    # Drop trailing zeros (extra zeros are allowed). A nonzero remainder whose
    # last significant digit lies below the cent position is not representable.
    coefficient = "".join(map(str, digits)).rstrip("0")
    exponent += len(digits) - len(coefficient) if False else 0
    trailing = len("".join(map(str, digits))) - len(coefficient)
    exponent += trailing
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")

    cents = int(coefficient) * 10 ** (exponent + 2)
    if cents < 1 or cents > MAX_CENTS:
        raise ValueError("amount out of range")
    return cents


def from_cents(cents):
    """Return an exact Decimal with exponent -2 for an integer cent count."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return from_cents(to_cents(value))


def format_amount(value):
    return format(value, ".2f")
